/* Automated test driver for Lab 08. DO NOT EDIT THIS FILE. */
public class Lab08MethodDesignTest {

    public static void main(String[] args) {

        TestRunner.section("Overloaded describe methods");
        TestRunner.check("describe(int)", "int: 5", Lab08MethodDesign.describe(5));
        TestRunner.check("describe(int) negative", "int: -12", Lab08MethodDesign.describe(-12));
        TestRunner.check("describe(double)", "double: 5.5", Lab08MethodDesign.describe(5.5));
        TestRunner.check("describe(String)", "String: hello", Lab08MethodDesign.describe("hello"));
        TestRunner.check("describe(String) empty", "String: ", Lab08MethodDesign.describe(""));

        TestRunner.section("gcd");
        TestRunner.check("gcd(48, 18)", 6, Lab08MethodDesign.gcd(48, 18));
        TestRunner.check("gcd(18, 48) - order does not matter", 6, Lab08MethodDesign.gcd(18, 48));
        TestRunner.check("gcd(17, 5) - coprime", 1, Lab08MethodDesign.gcd(17, 5));
        TestRunner.check("gcd(12, 0)", 12, Lab08MethodDesign.gcd(12, 0));
        TestRunner.check("gcd with a negative argument returns 0", 0, Lab08MethodDesign.gcd(-4, 8));

        TestRunner.section("reverseDigits");
        TestRunner.check("reverseDigits(1234)", 4321, Lab08MethodDesign.reverseDigits(1234));
        TestRunner.check("reverseDigits(1200) drops leading zeros", 21, Lab08MethodDesign.reverseDigits(1200));
        TestRunner.check("reverseDigits(7) single digit", 7, Lab08MethodDesign.reverseDigits(7));
        TestRunner.check("reverseDigits(0)", 0, Lab08MethodDesign.reverseDigits(0));
        TestRunner.check("reverseDigits(-5) returns -1", -1, Lab08MethodDesign.reverseDigits(-5));

        TestRunner.section("countVowels");
        TestRunner.check("countVowels(\"Programming\")", 3, Lab08MethodDesign.countVowels("Programming"));
        TestRunner.check("countVowels(\"AEIOU\") upper case counts", 5, Lab08MethodDesign.countVowels("AEIOU"));
        TestRunner.check("countVowels(\"rhythm\")", 0, Lab08MethodDesign.countVowels("rhythm"));
        TestRunner.check("countVowels(\"\")", 0, Lab08MethodDesign.countVowels(""));
        TestRunner.check("countVowels(null) is guarded", 0, Lab08MethodDesign.countVowels(null));

        TestRunner.section("isPalindrome");
        TestRunner.checkTrue("racecar", Lab08MethodDesign.isPalindrome("racecar"));
        TestRunner.checkTrue("RaceCar - case is ignored", Lab08MethodDesign.isPalindrome("RaceCar"));
        TestRunner.checkTrue("a single character", Lab08MethodDesign.isPalindrome("Z"));
        TestRunner.checkFalse("java", Lab08MethodDesign.isPalindrome("java"));
        TestRunner.checkFalse("null is not a palindrome", Lab08MethodDesign.isPalindrome(null));

        TestRunner.exitWithSummary();
    }
}
